// Some portions generated by Claude
import { graphNodeSize } from "./graph-geometry.ts";
import { LAYOUT_SPACING as gap } from "./graph-layout-spacing.ts";
import type { Graph, PointerPosition } from "./graph-types.ts";

const byX = (a: Graph["nodes"][number], b: Graph["nodes"][number]) => (a.x ?? 0) - (b.x ?? 0) || a.id.localeCompare(b.id);

/**
 * A grid with as many columns as rows (the last row may be short), filled in the order a person reads the nodes where
 * they stand now: top to bottom in bands one row tall, left to right within a band. Each column is as wide as its
 * widest card and each row as tall as its tallest, with the layout gaps between them. The grid is centred on the origin.
 */
export function computeSquareLayout(graph: Pick<Graph, "nodes">): Map<string, PointerPosition> {
  const positions = new Map<string, PointerPosition>();
  const nodes = graph.nodes;
  if (!nodes.length) return positions;
  const columns = Math.ceil(Math.sqrt(nodes.length));
  const reading = [...nodes].sort((a, b) => (a.y ?? 0) - (b.y ?? 0) || byX(a, b));
  const rows: Graph["nodes"][] = [];
  for (let start = 0; start < reading.length; start += columns) rows.push(reading.slice(start, start + columns).sort(byX));
  const widths = new Array<number>(columns).fill(0);
  const heights = rows.map((row) =>
    row.reduce((tallest, node, column) => {
      const size = graphNodeSize(node);
      widths[column] = Math.max(widths[column], size.width);
      return Math.max(tallest, size.height);
    }, 0),
  );
  const centres = (spans: number[], spacing: number) => {
    const result: number[] = [];
    let offset = 0;
    for (const span of spans) {
      result.push(offset + span / 2);
      offset += span + spacing;
    }
    // The middle of the first and the last centre lands on the origin.
    const middle = (result[0] + result[result.length - 1]) / 2;
    return result.map((centre) => centre - middle);
  };
  const xs = centres(widths.filter((width) => width > 0), gap.nodeGapX);
  const ys = centres(heights, gap.nodeGapY);
  rows.forEach((row, r) => row.forEach((node, c) => positions.set(node.id, { x: xs[c], y: ys[r] })));
  return positions;
}
